import copy


def redact(value, sensitive):
    """
    Recursively copy JSON-like dictionaries/lists.

    Replace any dictionary value whose key case-insensitively matches 
    any string in `sensitive` with "[REDACTED]".

    Sensitive matching is exact (case-insensitive), not substring.
    Preserve unrelated scalars and do not mutate input.

    Args:
        value: JSON-like structure (dict, list, or scalar).
        sensitive: List of strings to match against dictionary keys.

    Returns:
        A new copy of the input with sensitive values redacted.
    """
    # Normalize sensitive keys for case-insensitive exact matching
    sensitive_lower = {s.lower() for s in sensitive}

    if isinstance(value, dict):
        result = {}
        for key, val in value.items():
            if key.lower() in sensitive_lower:
                result[key] = "[REDACTED]"
            else:
                result[key] = redact(val, sensitive)
        return result
    elif isinstance(value, list):
        return [redact(item, sensitive) for item in value]
    else:
        # Scalar values (int, float, str, bool, None, etc.) are preserved as-is.
        # Use copy.deepcopy to ensure we don't mutate any mutable scalar-like objects,
        # but for typical JSON scalars, returning the value directly is fine.
        # To be safe and avoid mutation issues, return a copy for mutable types.
        if isinstance(value, (dict, list)):
            return copy.deepcopy(value)
        return value
