class LRU:
    def __init__(self, capacity):
        if not isinstance(capacity, int) or capacity < 1:
            raise ValueError("capacity must be an integer >= 1")
        self.capacity = capacity
        # OrderedDict preserves insertion order; we move items to end on access
        self.cache = {}

    def get(self, key):
        if key not in self.cache:
            return None
        # Move key to the end (most recently used)
        value = self.cache[key]
        del self.cache[key]
        self.cache[key] = value
        return value

    def put(self, key, value):
        if key in self.cache:
            # Update existing key and move to most recently used
            del self.cache[key]
        elif len(self.cache) >= self.capacity:
            # Evict the least recently used (first item in dict)
            oldest = next(iter(self.cache))
            del self.cache[oldest]
        self.cache[key] = value
