def changed_paths(before, after):
    """
    Compare two JSON-like dict roots and return sorted dot-separated paths
    for additions, removals, or unequal leaves.

    Rules:
    - Recurse only where BOTH values are dictionaries.
    - Treat lists atomically (compare as single values).
    - If an entire dictionary key is added/removed, return that parent path only.
    - String keys never contain dots.
    """

    def _compare(before_val, after_val, path):
        results = []

        # If both are dictionaries, recurse into them
        if isinstance(before_val, dict) and isinstance(after_val, dict):
            # Check for removed keys (in before but not in after)
            for key in before_val:
                if key not in after_val:
                    results.append(path + key if path else key)

            # Check for added keys (in after but not in before)
            for key in after_val:
                if key not in before_val:
                    results.append(path + key if path else key)

            # Check for changed values in common keys
            for key in before_val:
                if key in after_val:
                    new_path = path + key if path else key
                    results.extend(_compare(before_val[key], after_val[key], new_path))
        else:
            # If not both dicts, compare as atomic values
            if before_val != after_val:
                results.append(path)

        return results

    paths = _compare(before, after, "")
    return sorted(paths)
