class LRU:
    def __init__(self, capacity):
        if capacity < 1:
            raise ValueError("capacity must be >= 1")
        self.capacity = capacity
        self.cache = {}
        # Use OrderedDict to maintain insertion order (LRU order)
        from collections import OrderedDict
        self.order = OrderedDict()

    def get(self, key):
        if key not in self.cache:
            return None
        # Move the key to the end (most recently used)
        self.order.move_to_end(key)
        return self.cache[key]

    def put(self, key, value):
        if key in self.cache:
            # Update value and move to end
            self.cache[key] = value
            self.order.move_to_end(key)
        else:
            if len(self.cache) >= self.capacity:
                # Evict the least recently used (first item in order)
                oldest_key = next(iter(self.order))
                del self.cache[oldest_key]
                del self.order[oldest_key]
            self.cache[key] = value
            self.order[key] = None

    def __repr__(self):
        return f"LRU(capacity={self.capacity}, cache={dict(self.cache)})"
