import json


def changed_paths(before, after):
    """
    Compare two JSON-like dictionaries and return sorted dot-separated paths
    for additions, removals, or unequal leaves.

    Rules:
    - Recurse only where BOTH values are dictionaries.
    - Treat lists atomically (no recursion into list elements).
    - If an entire dictionary key is added/removed, return that parent path only.
    - String keys never contain dots.
    - Return sorted list of paths as strings.

    Args:
        before: A dict representing the original JSON-like structure.
        after:  A dict representing the modified JSON-like structure.

    Returns:
        Sorted list of dot-separated path strings for differences.
    """
    def _compare(obj1, obj2, path):
        results = []

        # If both are dicts, recurse
        if isinstance(obj1, dict) and isinstance(obj2, dict):
            keys1 = set(obj1.keys())
            keys2 = set(obj2.keys())

            # Keys only in obj1 (removed)
            for key in keys1 - keys2:
                results.append(path + key if path else key)

            # Keys only in obj2 (added)
            for key in keys2 - keys1:
                results.append(path + key if path else key)

            # Common keys: recurse
            for key in keys1 & keys2:
                new_path = path + key if path else key
                results.extend(_compare(obj1[key], obj2[key], new_path))

        elif isinstance(obj1, dict) and not isinstance(obj2, dict):
            # obj1 is dict, obj2 is not: treat as unequal leaf at this level
            # But we need to handle the case where obj1 was a dict and obj2 is something else
            # The path here represents the key that led to obj1/obj2 comparison.
            # If path is empty, it means root level difference.
            if path:
                results.append(path)
            else:
                # Root-level type mismatch; no key name available in path.
                # This shouldn't happen per spec since roots are dicts.
                pass

        elif not isinstance(obj1, dict) and isinstance(obj2, dict):
            # obj1 is not dict, obj2 is dict
            if path:
                results.append(path)
            else:
                pass

        else:
            # Neither is a dict (or both are non-dict types like lists, scalars)
            # Treat as atomic leaf comparison
            if obj1 != obj2:
                if path:
                    results.append(path)
                else:
                    pass

        return results

    # Ensure roots are dicts per spec; but handle gracefully
    if not isinstance(before, dict):
        before = {}
    if not isinstance(after, dict):
        after = {}

    paths = _compare(before, after, "")
    return sorted(paths)
