class LRU:
    def __init__(self, capacity):
        if capacity < 1:
            raise ValueError("capacity must be >= 1")
        self.capacity = capacity
        # OrderedDict maintains insertion order; we can move keys to end on access
        self.cache = {}
        # Use a list of keys in LRU order (least recently used first, most recently used last)
        self.order = []

    def get(self, key):
        if key not in self.cache:
            return None
        # Move key to the end (most recently used)
        if key in self.order:
            self.order.remove(key)
        self.order.append(key)
        return self.cache[key]

    def put(self, key, value):
        if key in self.cache:
            # Update value and move to most recently used
            self.cache[key] = value
            if key in self.order:
                self.order.remove(key)
            self.order.append(key)
        else:
            # Insert new key-value pair
            self.cache[key] = value
            self.order.append(key)
            # Evict least recently used if over capacity
            if len(self.order) > self.capacity:
                lru_key = self.order[0]
                del self.cache[lru_key]
                self.order.pop(0)

    def _evict(self):
        """Evict the least recently used key."""
        if not self.order:
            return
        lru_key = self.order[0]
        del self.cache[lru_key]
        self.order.pop(0)
